INSERT INTO questions (code, topic, subtopic, difficulty, type, statement, options, answer_key, explanation, rubric, test_cases, time_estimate_sec, version, active) VALUES
('JAVA-001','JAVA','Strings','EASY','MCQ','Given String a = new String("hi"); String b = "hi"; what does (a == b) evaluate to?','[{"id":"A","text":"true, both hold the same characters"},{"id":"B","text":"false, == compares references and a is a new heap object"},{"id":"C","text":"Compile error"},{"id":"D","text":"Depends on the JVM vendor"}]','B','The == operator compares references. new String(...) always allocates a new object, so it differs from the pooled literal.',NULL,NULL,60,1,TRUE),
('JAVA-002','JAVA','Collections','EASY','MCQ','Which collection guarantees insertion-order iteration and permits null keys?','[{"id":"A","text":"HashMap"},{"id":"B","text":"TreeMap"},{"id":"C","text":"LinkedHashMap"},{"id":"D","text":"ConcurrentHashMap"}]','C','LinkedHashMap keeps a linked list of entries in insertion order and, like HashMap, allows one null key.',NULL,NULL,60,1,TRUE),
('JAVA-003','JAVA','Collections','MEDIUM','SHORT','Explain how HashMap uses hashCode() and equals() when storing and retrieving a key.',NULL,NULL,NULL,'[{"name":"hashCode selects bucket","keywords":["hashcode","hash code"],"weight":1},{"name":"equals resolves collisions","keywords":["equals"],"weight":1},{"name":"bucket / collision handling","keywords":["bucket","collision","chain","tree"],"weight":1}]',NULL,180,1,TRUE),
('JAVA-004','JAVA','Concurrency','MEDIUM','MCQ','What does the volatile keyword guarantee for a field?','[{"id":"A","text":"Atomic compound updates such as i++"},{"id":"B","text":"Visibility of writes across threads and a happens-before edge"},{"id":"C","text":"Mutual exclusion"},{"id":"D","text":"Thread-local storage"}]','B','volatile gives visibility and ordering guarantees but does not make compound operations atomic.',NULL,NULL,60,1,TRUE),
('JAVA-005','JAVA','Memory','MEDIUM','LONG','Describe how garbage collection decides an object can be reclaimed, and name two generations or regions the heap is divided into.',NULL,NULL,NULL,'[{"name":"reachability from GC roots","keywords":["reachab","gc root","root"],"weight":1},{"name":"generational heap","keywords":["young","old","eden","survivor","generation","region"],"weight":1},{"name":"mark phase / sweep or copy","keywords":["mark","sweep","copy","compact"],"weight":1},{"name":"stop-the-world or pauses","keywords":["stop-the-world","pause","stop the world"],"weight":1}]',NULL,300,1,TRUE),
('JAVA-006','JAVA','Concurrency','HARD','LONG','Compare synchronized blocks with java.util.concurrent.locks.ReentrantLock. When would you pick each?',NULL,NULL,NULL,'[{"name":"intrinsic monitor / automatic release","keywords":["monitor","automatic","intrinsic","block scope"],"weight":1},{"name":"tryLock / timeout / interruptible","keywords":["trylock","timeout","interrupt"],"weight":1},{"name":"fairness option","keywords":["fair"],"weight":1},{"name":"condition variables","keywords":["condition","await","signal"],"weight":1},{"name":"must unlock in finally","keywords":["finally","unlock"],"weight":1}]',NULL,360,1,TRUE),
('JAVA-007','JAVA','Strings','MEDIUM','CODING','Write a method that returns true if two strings are anagrams, ignoring case and spaces.',NULL,NULL,NULL,NULL,'[{"input":"\"Dormitory\",\"Dirty room\"","expected":"true"},{"input":"\"abc\",\"abd\"","expected":"false"}]',600,1,TRUE),
('OOP-001','OOP','Polymorphism','EASY','MCQ','Method overriding is an example of which kind of polymorphism?','[{"id":"A","text":"Compile-time (static)"},{"id":"B","text":"Runtime (dynamic)"},{"id":"C","text":"Parametric only"},{"id":"D","text":"None of the above"}]','B','The method actually invoked is chosen at runtime from the object''s concrete class.',NULL,NULL,60,1,TRUE),
('OOP-002','OOP','Abstraction','EASY','MCQ','Which statement about an abstract class is correct?','[{"id":"A","text":"It can be instantiated directly"},{"id":"B","text":"It can contain both abstract and concrete methods"},{"id":"C","text":"It cannot have constructors"},{"id":"D","text":"It cannot have fields"}]','B','Abstract classes may mix concrete and abstract members and may declare constructors and fields.',NULL,NULL,60,1,TRUE),
('OOP-003','OOP','Principles','MEDIUM','SHORT','What is the Liskov Substitution Principle? Give a violation example.',NULL,NULL,NULL,'[{"name":"subtypes substitutable for base type","keywords":["substitut","replace"],"weight":1},{"name":"without breaking correctness","keywords":["correct","behavio","contract","break"],"weight":1},{"name":"example such as Square/Rectangle","keywords":["square","rectangle","example","throws"],"weight":1}]',NULL,180,1,TRUE),
('OOP-004','OOP','Design','MEDIUM','LONG','Explain the difference between composition and inheritance and why ''favor composition over inheritance'' is common advice.',NULL,NULL,NULL,'[{"name":"is-a vs has-a","keywords":["is-a","has-a","is a","has a"],"weight":1},{"name":"tight coupling of inheritance","keywords":["coupl","fragile","base class"],"weight":1},{"name":"flexibility / runtime change of composition","keywords":["flexib","runtime","swap","delegat"],"weight":1},{"name":"reuse via delegation","keywords":["reuse","delegat"],"weight":1}]',NULL,300,1,TRUE),
('OOP-005','OOP','Encapsulation','MEDIUM','MCQ','Why are fields usually declared private with accessor methods?','[{"id":"A","text":"It makes the program faster"},{"id":"B","text":"It allows invariants to be enforced and internals to change without breaking callers"},{"id":"C","text":"Java requires it"},{"id":"D","text":"It removes the need for constructors"}]','B','Encapsulation hides representation and lets a class protect its invariants.',NULL,NULL,60,1,TRUE),
('OOP-006','OOP','Patterns','HARD','LONG','Describe the Strategy pattern, a situation where it fits, and how it relates to the Open/Closed Principle.',NULL,NULL,NULL,'[{"name":"family of interchangeable algorithms","keywords":["interchangeable","family","algorithm"],"weight":1},{"name":"context delegates to strategy interface","keywords":["context","interface","delegate"],"weight":1},{"name":"add new strategy without modifying context","keywords":["open","closed","extend","without modif"],"weight":1},{"name":"example such as sorting or pricing","keywords":["sort","pricing","payment","discount","compress"],"weight":1}]',NULL,300,1,TRUE),
('DSA-001','DSA','Complexity','EASY','MCQ','What is the average time complexity of lookup in a hash table?','[{"id":"A","text":"O(n)"},{"id":"B","text":"O(log n)"},{"id":"C","text":"O(1)"},{"id":"D","text":"O(n log n)"}]','C','With a good hash function and load factor, lookups are constant time on average.',NULL,NULL,45,1,TRUE),
('DSA-002','DSA','Stacks','EASY','MCQ','Which data structure is the natural fit for checking balanced parentheses?','[{"id":"A","text":"Queue"},{"id":"B","text":"Stack"},{"id":"C","text":"Heap"},{"id":"D","text":"Trie"}]','B','A stack records the most recent unmatched opener, which is what a closer must match.',NULL,NULL,45,1,TRUE),
('DSA-003','DSA','Searching','MEDIUM','MCQ','Binary search on a sorted array of n elements takes how many comparisons in the worst case?','[{"id":"A","text":"O(1)"},{"id":"B","text":"O(log n)"},{"id":"C","text":"O(n)"},{"id":"D","text":"O(n log n)"}]','B','Each comparison halves the remaining range.',NULL,NULL,60,1,TRUE),
('DSA-004','DSA','Sorting','MEDIUM','SHORT','Compare quicksort and merge sort in terms of time complexity, space and stability.',NULL,NULL,NULL,'[{"name":"quicksort average n log n, worst n^2","keywords":["n log n","nlogn","n^2","quadratic"],"weight":1},{"name":"merge sort n log n always","keywords":["merge"],"weight":1},{"name":"merge sort extra space / quicksort in place","keywords":["extra space","in-place","in place","o(n) space"],"weight":1},{"name":"stability","keywords":["stable","stability"],"weight":1}]',NULL,240,1,TRUE),
('DSA-005','DSA','Graphs','HARD','LONG','Explain Dijkstra''s algorithm, the data structure that makes it efficient, its time complexity and why negative edge weights break it.',NULL,NULL,NULL,'[{"name":"greedy shortest path from source","keywords":["greedy","shortest","source"],"weight":1},{"name":"priority queue / min-heap","keywords":["priority queue","min-heap","heap"],"weight":1},{"name":"complexity (E+V) log V","keywords":["log v","e log","(e + v)","e+v"],"weight":1},{"name":"negative edges invalidate finalized distances","keywords":["negative"],"weight":1}]',NULL,360,1,TRUE),
('DSA-006','DSA','Arrays','EASY','CODING','Given an int array and a target, return the indices of two numbers that sum to target in O(n) time.',NULL,NULL,NULL,NULL,'[{"input":"[2,7,11,15], 9","expected":"[0,1]"},{"input":"[3,2,4], 6","expected":"[1,2]"}]',600,1,TRUE),
