('DSA-008','DSA','Trees','MEDIUM','MCQ','What is the in-order traversal of a binary search tree?','[{"id":"A","text":"Nodes in level order"},{"id":"B","text":"Nodes in ascending key order"},{"id":"C","text":"Nodes in descending key order"},{"id":"D","text":"Nodes in insertion order"}]','B','Left-root-right visits keys in sorted order for a BST.',NULL,NULL,60,1,TRUE),
('DSA-009','DSA','Dynamic programming','HARD','LONG','What are overlapping subproblems and optimal substructure? Explain how memoization versus tabulation applies them to the Fibonacci or knapsack problem.',NULL,NULL,NULL,'[{"name":"overlapping subproblems","keywords":["overlapping"],"weight":1},{"name":"optimal substructure","keywords":["optimal substructure"],"weight":1},{"name":"memoization top-down","keywords":["memo","top-down","top down","cache"],"weight":1},{"name":"tabulation bottom-up","keywords":["tabulation","bottom-up","bottom up","table"],"weight":1}]',NULL,360,1,TRUE),
('DBMS-001','DBMS','Keys','EASY','MCQ','Which constraint uniquely identifies each row and cannot be NULL?','[{"id":"A","text":"Foreign key"},{"id":"B","text":"Primary key"},{"id":"C","text":"Check constraint"},{"id":"D","text":"Index"}]','B','A primary key is unique and not null.',NULL,NULL,45,1,TRUE),
('DBMS-002','DBMS','Transactions','EASY','MCQ','In ACID, what does the ''I'' stand for?','[{"id":"A","text":"Integrity"},{"id":"B","text":"Isolation"},{"id":"C","text":"Indexing"},{"id":"D","text":"Idempotency"}]','B','Isolation: concurrent transactions do not see each other''s partial effects.',NULL,NULL,45,1,TRUE),
('DBMS-003','DBMS','Normalization','MEDIUM','SHORT','What is the difference between 2NF and 3NF?',NULL,NULL,NULL,'[{"name":"2NF removes partial dependency on part of a composite key","keywords":["partial"],"weight":1},{"name":"3NF removes transitive dependency","keywords":["transitive"],"weight":1},{"name":"non-key attributes depend on the key","keywords":["non-key","non key","nonkey","candidate key","primary key"],"weight":1}]',NULL,200,1,TRUE),
('DBMS-004','DBMS','Indexing','MEDIUM','MCQ','A composite B-tree index on (a, b) can efficiently serve which query?','[{"id":"A","text":"WHERE b = 5"},{"id":"B","text":"WHERE a = 5 AND b > 2"},{"id":"C","text":"WHERE b > 2 ORDER BY a"},{"id":"D","text":"None of these"}]','B','The leftmost prefix column must be constrained for the index to be seekable.',NULL,NULL,75,1,TRUE),
